        vm.assume(blockTime1 < blockTime2);

        // First call to set pastBlockTime
        vm.warp(blockTime1);
        vm.deal(address(this), 10 ether);
        (bool success1,) = address(c).call{value: 10 ether}("");

        if (!success1) return; // if first call fails, skip

        // Second call with later time
        vm.warp(blockTime2);
        (bool success2,) = address(c).call{value: 10 ether}("");

        if (!success2) return; // if second call fails, skip

        // After two successful calls, pastBlockTime should always be > block.timestamp of first call
        // In reference: after first call, pastBlockTime = blockTime1; after second call, pastBlockTime = blockTime2
        // In mutant: after first call, pastBlockTime = blockTime1+1; after second call, pastBlockTime = blockTime2+1
        // Property: pastBlockTime (after second call) > blockTime1
        // Reference satisfies: blockTime2 > blockTime1 (true by assumption)
        // Mutant violates: blockTime2+1 could be <= blockTime1? No, but the point is pastBlockTime differs
        // Actually: For mutant, after first call, pastBlockTime = blockTime1+1 > blockTime1
        // For second call, require(block.timestamp > pastBlockTime) becomes require(blockTime2 > blockTime1+1)
        // This might fail if blockTime2 == blockTime1+1 (which is allowed by assumption)
        // But the reference would succeed because require(blockTime2 > blockTime1)
        // So the difference is that mutant may revert when blockTime2 == blockTime1+1

        assertTrue(c.pastBlockTime() > blockTime1);
    }
}

