        // Fund the caller with 10 ETH
        address caller = address(0x1234);
        vm.deal(caller, 10 ether);

        // Call the fallback with 10 ETH
        vm.prank(caller);
        (bool success, ) = address(c).call{value: 10 ether}("");

        // If the call succeeded and block.number % 15 == 0, then transferred amount equals balance before
        uint256 balanceAfter = address(c).balance;
        uint256 transferred = balanceBefore + 10 ether - balanceAfter;

        // For reference C: if success and blockNumber % 15 == 0, transferred == balanceBefore
        // For buggy M: transferred will be 5 ether regardless
        if (success && blockNumber % 15 == 0) {
            assertTrue(transferred == balanceBefore, "Transferred amount should equal contract balance before transfer");
        } else {
            assertTrue(true); // No assertion when condition not met
        }
    }
}
